def next_smallest_palindrome(num):
    s = str(num)
    n = len(s)

    # Special case: all digits are 9 -> next palindrome is 10...01
    if all(c == '9' for c in s):
        return int('1' + '0' * (n - 1) + '1')

    # Extract left half (including middle for odd length)
    left = s[:(n + 1) // 2]

    # Helper to build palindrome from left half and length
    def make_pal(half, length):
        if length % 2 == 0:
            return half + half[::-1]
        else:
            # half includes middle, skip last char for mirroring
            return half + half[-2::-1]

    candidate = make_pal(left, n)
    if int(candidate) > num:
        return int(candidate)
    else:
        new_left = str(int(left) + 1)
        new_candidate = make_pal(new_left, n)
        return int(new_candidate)
