def next_smallest_palindrome(num):
    s = str(num)
    n = len(s)
    left_len = (n + 1) // 2
    left = s[:left_len]

    if n % 2 == 0:
        pal = left + left[::-1]
    else:
        pal = left + left[:-1][::-1]

    if int(pal) > num:
        return int(pal)

    new_left = str(int(left) + 1)

    if len(new_left) > len(left):
        return int('1' + '0' * (n - 1) + '1')

    if n % 2 == 0:
        new_pal = new_left + new_left[::-1]
    else:
        new_pal = new_left + new_left[:-1][::-1]

    return int(new_pal)

